import {readFileSync,readdirSync,existsSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {isDeepStrictEqual as equal} from 'node:util';
const output='.agentdoc/v07-setup-20260911T122653Z/evidence/final-v070-validation-analysis';
const root='.agentdoc/v07-setup-20260911T122653Z/evidence/validation-final-v070';
const reportPath='.agentdoc/v07-setup-20260911T122653Z/evidence/candidate-final-v070.json';
if(process.env.DESMON_VALIDATION_COMPLETE!=='final-v070')throw Error('Wait for Host COMPLETE notice; validation data access not authorized yet.');
const read=p=>JSON.parse(readFileSync(p,'utf8')),hash=b=>createHash('sha256').update(b).digest('hex'),fileHash=p=>hash(readFileSync(p)),objectHash=o=>hash(JSON.stringify(o));
const prep=read(output+'/preparation.json');
const executionPath=root+'/execution.json',execution=read(executionPath);
if(!execution.endedAt)throw Error('Incomplete execution: no report/raw/log/archive access.');
const errors=[],check=(ok,label)=>{if(!ok)errors.push(label);};
const protocolPath=root+'/protocol.adopted.json',protocol=read(protocolPath);
check(fileHash(protocolPath)===prep.protocol.sha256,'exact adopted protocol bytes');
check(equal(execution.protocol,{path:protocolPath,sha256:prep.protocol.sha256}),'execution adopted protocol binding');
check(protocol.round===8&&protocol.schemaVersion===2&&protocol.progressionParameterVersion===3&&protocol.phase==='candidate'&&protocol.experimentStage==='validation','protocol stage/version');
check(equal(protocol.selectedExperiment,prep.selectedExperiment)&&equal(execution.experiment,prep.selectedExperiment),'frozen selected experiment');
check(Date.parse(protocol.frozenAt)<=Date.parse(execution.startedAt)&&Date.parse(protocol.adoption.at)<=Date.parse(execution.startedAt),'adoption precedes execution');
check(fileHash(prep.script.path)===prep.script.sha256,'validation execution script unchanged');
check(execution.appVersion==='0.7.0','final version explicitly0.7.0');
check(equal(execution.seedSet,{name:'validation',start:1,count:100}),'execution validation seed set');
for(const key of ['preregisteredProtocol','independentAnalysis','hostCheck']){
 const a=protocol.adoption[key];check(a&&fileHash(a.path)===a.sha256,'preserved adoption artifact '+key);
}
const report=read(reportPath);
check(report.rawComplete===true&&report.phase==='candidate'&&report.seedSet==='validation'&&report.screening===false,'complete candidate validation report');
check(equal(report.seeds,{start:1,count:100})&&equal(report.runs.map(r=>r.seed).sort((a,b)=>a-b),Array.from({length:100},(_,i)=>i+1)),'all100 distinct validation seeds');
check(equal(report.protocol,protocol)&&report.protocolSha256===objectHash(protocol),'embedded adopted protocol binding');
check(equal(execution.report,{path:reportPath,sha256:fileHash(reportPath)}),'execution report file hash');
for(const k of ['sourceDigest','evaluationDigest','rawSha256','targets'])check(equal(execution[k],report[k]),'execution report '+k);
check(report.sourceDigest===prep.hostExpected.sourceDigest&&report.evaluationDigest===prep.hostExpected.evaluationDigest,'Host declared exact final S/E');
check(report.rawSha256===objectHash(report.runs),'report raw object hash');
check(report.fixture===null&&report.fixtureSha256===objectHash(null),'fresh fixture');
check(equal(report.settings,prep.measurementSettings),'frozen measurement settings including9 policy definitions');
const canonical=prep.measurementSettings.baseline;
check(equal(report.policies,[canonical]),'one canonical policy; no pooling9 policies');
check(equal(report.checkpointsMinutes,prep.measurementSettings.checkpointsMinutes)&&report.timing.modeledMinutes===720,'full12h checkpoints');
const experiment=protocol.candidates.find(e=>e.id===protocol.selectedExperiment.id);
check(experiment&&equal(experiment.parameters,prep.parameters)&&Object.keys(experiment.parameters).length===21,'registered21 selected parameters');
check(report.experiment.kind==='candidate'&&report.experiment.id===prep.selectedExperiment.id&&report.experiment.parametersSha256===objectHash(experiment.parameters),'report parameter binding');
const contentRules=Object.fromEntries(protocol.milestones.flatMap(m=>m.ids.map(id=>[id,m.requirements])));
check(report.experiment.contentRulesSha256===objectHash(contentRules)&&equal(protocol.milestones,prep.milestones),'six frozen content requirements');
const expectedCommands=[
 ['measure',['node','.harness/v7/loop/measure.mjs','run',reportPath,'--phase','candidate','--candidate',prep.selectedExperiment.id,'--seed-set','validation','--workers','4']],
 ['structural-verify',['node','.harness/v7/loop/measure.mjs','verify',reportPath]]
];
check(execution.commands.length===2,'two execution commands');
for(const [index,command] of execution.commands.entries()){
 const expected=expectedCommands[index];check(expected&&command.label===expected[0]&&equal(command.argv,expected[1]),'exact command '+index);
 check(command.log&&fileHash(command.log.path)===command.log.sha256,'command log hash '+index);
 check(Date.parse(command.startedAt)>=Date.parse(execution.startedAt)&&Date.parse(command.endedAt)<=Date.parse(execution.endedAt),'command chronology '+index);
 check(command.exitCode===(index===0?(report.targets.passed?0:1):0),'command exit matches actual target/structural '+index);
}
check(equal(execution.readinessChecks.map(c=>c.commandId).sort(),['gates','harness','progression']),'three preflight checks');
for(const c of execution.readinessChecks){
 check(c.exitCode===0&&c.sourceDigest===report.sourceDigest&&c.endedDigest===report.sourceDigest&&c.evaluationDigest===report.evaluationDigest&&c.endedEvaluationDigest===report.evaluationDigest,'same S/E preflight '+c.commandId);
 check(fileHash(c.log)===c.sha256,'preflight log hash '+c.commandId);
}
const archiveCache=new Map(),archiveInfo=[];
function archive(path){
 if(archiveCache.has(path))return archiveCache.get(path);
 const py='import tarfile,hashlib,json,sys,pathlib\nwith tarfile.open(sys.argv[1]) as t:\n ms=t.getmembers(); names=[m.name for m in ms]\n assert len(names)==len(set(names))\n assert all(not pathlib.PurePosixPath(n).is_absolute() and ".." not in pathlib.PurePosixPath(n).parts for n in names)\n assert all(m.isfile() or m.isdir() for m in ms)\n print(json.dumps({m.name:hashlib.sha256(t.extractfile(m).read()).hexdigest() for m in ms if m.isfile()}))';
 const res=spawnSync('python3',['-c',py,path],{encoding:'utf8'});if(res.status!==0)throw Error(res.stderr);
 const files=JSON.parse(res.stdout);archiveCache.set(path,files);archiveInfo.push({path,sha256:fileHash(path),fileMembers:Object.keys(files).length,uniqueSafePaths:true});return files;
}
function archiveText(path,member){
 const py='import tarfile,sys\nwith tarfile.open(sys.argv[1]) as t: sys.stdout.write(t.extractfile(sys.argv[2]).read().decode())';
 const res=spawnSync('python3',['-c',py,path,member],{encoding:'utf8'});if(res.status!==0)throw Error(res.stderr);return res.stdout;
}
function exportedParameters(text){
 const body=text.match(/PROGRESSION_PARAMETERS[^=\n]*=\s*Object\.freeze\(\{([\s\S]*?)\}\)/)?.[1];
 if(!body)throw Error('Missing actual frozen progression object');
 return JSON.parse('{'+body.replace(/^(\s*)([A-Za-z]\w*)(\s*:)/gm,'$1"$2"$3').replace(/,\s*$/,'')+'}');
}
for(const k of ['sourceArchive','evaluationArchive','buildArchive'])check(execution[k]&&fileHash(execution[k].path)===execution[k].sha256,k+' literal hash');
const src=archive(execution.sourceArchive.path),ev=archive(execution.evaluationArchive.path),build=archive(execution.buildArchive.path);
check(Object.keys(src).every(p=>!p.startsWith('Users/')),'root-relative source including tsconfigs');
const sourceFiles=Object.fromEntries(Object.entries(src).filter(([p])=>p.startsWith('src/')||p.startsWith('static/')||/^(package(-lock)?|tsconfig[^/]*)\.json$/.test(p)));
check(hash(Object.keys(sourceFiles).sort().map(p=>p+'\0'+sourceFiles[p]).join('\n'))===report.sourceDigest,'archived source digest');
const evaluationFiles=Object.fromEntries(Object.entries(ev).filter(([p])=>p.startsWith('.harness/v7/')||p==='docs/v0.7/EVALUATION_PROTOCOL.json'));
check(hash(Object.entries(evaluationFiles).sort(([a],[b])=>a.localeCompare(b)).map(([p,h])=>p+'\0'+h).join('\n'))===report.evaluationDigest,'archived evaluator digest');
check(ev['docs/v0.7/EVALUATION_PROTOCOL.json']===prep.protocol.sha256,'archived official protocol bytes');
check(report.build.sha256===objectHash(report.build.files),'build manifest hash');
for(const [p,h] of Object.entries(report.build.files))check(build[p]===h,'archived compiled file '+p);
const compiledPath=Object.keys(build).find(p=>p.endsWith('/core/progression.js'));
check(Boolean(compiledPath),'compiled progression exists');
const sourceParameters=exportedParameters(archiveText(execution.sourceArchive.path,'src/core/progression.ts'));
const compiledParameters=compiledPath?exportedParameters(archiveText(execution.buildArchive.path,compiledPath)):null;
check(equal(sourceParameters,experiment.parameters)&&equal(compiledParameters,experiment.parameters),'actual source and compiled21 parameter equality');
const packageInfo=JSON.parse(archiveText(execution.sourceArchive.path,'package.json')),lock=JSON.parse(archiveText(execution.sourceArchive.path,'package-lock.json'));
check(packageInfo.version==='0.7.0'&&lock.version==='0.7.0'&&lock.packages[''].version==='0.7.0','final package/lock actual version');
const manifestPath=reportPath+'.runs/manifest.json',manifest=read(manifestPath);
check(manifest.binding===objectHash(manifest.identity),'manifest binding');
for(const k of ['sourceDigest','evaluationDigest','protocolSha256','fixtureSha256','seedSet','seeds','policies','settings','screening','checkpointsMinutes','experiment'])check(equal(manifest.identity[k],report[k]),'manifest identity '+k);
check(manifest.identity.buildSha256===report.build.sha256,'manifest build binding');
const policyHash=hash(Object.values(canonical).join('/')),runRoot=reportPath+'.runs';
const walk=dir=>readdirSync(dir,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(dir+'/'+e.name):[dir+'/'+e.name]);
const files=walk(runRoot),expectedFiles=[manifestPath,...Array.from({length:100},(_,i)=>runRoot+'/'+policyHash+'/'+(i+1)+'.json')];
check(equal([...files].sort(),expectedFiles.sort()),'manifest1+exact100 seed files only');
const popQ=(xs,q)=>{const sorted=[...xs].sort((a,b)=>(a??Infinity)-(b??Infinity));return sorted.length?sorted[Math.floor((sorted.length-1)*q)]:null;};
function stats(xs){
 check(xs.every(v=>v===null||typeof v==='number'&&Number.isFinite(v)),'finite statistics');
 const ys=xs.filter(v=>v!==null),quantiles=vs=>({p10:popQ(vs,.1),p50:popQ(vs,.5),p90:popQ(vs,.9),worst:popQ(vs,1)});
 return {samples:xs.length,reached:ys.length,unreached:xs.length-ys.length,population:quantiles(xs),conditional:quantiles(ys),minimum:ys.length?Math.min(...ys):null};
}
const firstNames=['firstKillSec','firstRewardSec','firstLevelSec','firstCaptureSec','firstReadySec','firstOpenSec','firstAcceptedSec'];
const numberFields=['level','kills','coins','income','spent','companions','maxCompanionLevel','reincarnations','training','offers','rerolls','managementActions','feverStarts','inputCount','longestKillGapSec','longestMeaningfulGapSec','longestDiscoveryGapSec','eligibleHeroCount','eligibleMonsterCount','seenHeroCount','seenMonsterCount','chosenHeroCount','killedMonsterCount','capturedMonsterCount'];
const event=(run,kind,id='')=>{const rows=run.records.filter(r=>r.kind===kind&&r.id===id);check(rows.length<=1,'unique event '+run.seed+'/'+kind+'/'+id);return rows[0]?.sec??null;};
const rows=[],rawFiles=[];
for(const run of report.runs){
 const path=runRoot+'/'+policyHash+'/'+run.seed+'.json',raw=read(path);check(raw.binding===manifest.binding&&raw.sha256===objectHash(raw.run)&&equal(raw.run,run),'raw seed binding '+run.seed);rawFiles.push({path,sha256:fileHash(path),runSha256:raw.sha256});
 check(equal(run.policy,canonical)&&Object.values(run.initial).every(v=>v===0),'fresh canonical run '+run.seed);
 check(equal(run.checkpoints.map(c=>c.minutes),report.checkpointsMinutes),'full checkpoints '+run.seed);
 for(const cp of run.checkpoints){
  check(run.initial.coins+cp.income-cp.spent===cp.coins,'gold conservation '+run.seed+'/'+cp.minutes);
  for(const n of ['coins','income','spent','level','kills','companions','maxCompanionLevel'])check(Number.isSafeInteger(cp[n])&&cp[n]>=0,'safe integer '+run.seed+'/'+n);
  for(const n of ['heroDamage','companionDamage','partyPower'])check(typeof cp[n]==='string'&&/^(0|[1-9][0-9]*)$/.test(cp[n]),'exact bigint '+run.seed+'/'+n);
 }
 const last=run.checkpoints.at(-1),row={seed:run.seed,...Object.fromEntries(firstNames.map(n=>[n,event(run,n)])),h70EligibleSec:event(run,'eligibleHero','h70'),h70SeenSec:event(run,'seenHero','h70'),h70ChosenSec:event(run,'chosenHero','h70')};
 for(const n of firstNames)check(last[n]===row[n],'checkpoint event '+run.seed+'/'+n);
 check(last.lastUnlockSec===row.h70EligibleSec,'final named eligibility '+run.seed);
 if(row.firstOpenSec!==null)check(row.firstReadySec!==null&&row.firstReadySec<=row.firstOpenSec,'ready/open order '+run.seed);
 if(row.firstAcceptedSec!==null)check(row.firstOpenSec!==null&&row.firstOpenSec<=row.firstAcceptedSec,'open/accepted order '+run.seed);
 row.readyToOpenSec=row.firstReadySec===null||row.firstOpenSec===null?null:(Math.round(row.firstOpenSec*10)-Math.round(row.firstReadySec*10))/10;
 row.openToAcceptedSec=row.firstOpenSec===null||row.firstAcceptedSec===null?null:(Math.round(row.firstAcceptedSec*10)-Math.round(row.firstOpenSec*10))/10;
 row.distinctChosenHeroIds=[...new Set(run.actions.filter(a=>a.type==='heroChoose').map(a=>a.formId))];check(row.distinctChosenHeroIds.length===last.chosenHeroCount,'distinct actual chosen '+run.seed);
 row.terminal=Object.fromEntries(numberFields.map(n=>[n,last[n]]));row.exact={heroDamage:last.heroDamage,companionDamage:last.companionDamage,partyPower:last.partyPower};rows.push(row);
}
const metrics=Object.fromEntries([...firstNames,'h70EligibleSec','h70SeenSec','h70ChosenSec','readyToOpenSec','openToAcceptedSec'].map(n=>[n,stats(rows.map(r=>r[n]))]));
const firstMedian=metrics.firstAcceptedSec.population.p50,lastMedian=metrics.h70EligibleSec.population.p50,by90=rows.filter(r=>r.firstAcceptedSec!==null&&r.firstAcceptedSec<=5400).length;
const goals={firstMedian:{observedSec:firstMedian,minSec:2700,maxSec:3600,passed:firstMedian!==null&&firstMedian>=2700&&firstMedian<=3600},firstDeadline:{reached:by90,samples:100,required:90,deadlineSec:5400,passed:by90>=90},lastMedian:{id:'h70',observedSec:lastMedian,minSec:28800,maxSec:43200,passed:lastMedian!==null&&lastMedian>=28800&&lastMedian<=43200}};
const targetPassed=Object.values(goals).every(g=>g.passed);check(report.targets.passed===targetPassed&&report.targets.samples===100,'full100 target verdict');
const target=id=>report.targets.checks.find(c=>c.id===id);
check(target('first-reincarnation-median')?.observedSec===firstMedian&&target('first-reincarnation-median')?.passed===goals.firstMedian.passed,'reported first population goal');
check(target('first-reincarnation-deadline')?.reached===by90&&target('first-reincarnation-deadline')?.samples===100&&target('first-reincarnation-deadline')?.passed===goals.firstDeadline.passed,'reported deadline full100');
check(target('last-unlock-median')?.observedSec===lastMedian&&target('last-unlock-median')?.passed===goals.lastMedian.passed,'reported final population goal');
for(const scenario of report.scenarios){
 const cs=report.runs.map(r=>r.checkpoints.find(c=>c.minutes===scenario.minutes));
 for(const name of [...firstNames,'lastUnlockSec',...numberFields]){
  const s=stats(cs.map(c=>c[name])),reported=scenario.metrics[name];for(const k of ['samples','reached','unreached'])check(reported[k]===s[k],'scenario denominator '+scenario.minutes+'/'+name+'/'+k);
  for(const k of ['p10','p50','p90'])check(reported[k]===s.conditional[k],'conditional summary '+scenario.minutes+'/'+name+'/'+k);
 }
}
const milestones=protocol.milestones.map(m=>({...m,eligible:stats(report.runs.map(r=>event(r,m.kind==='hero'?'eligibleHero':'eligibleMonster',m.id))),seen:stats(report.runs.map(r=>event(r,m.kind==='hero'?'seenHero':'seenMonster',m.id))),acquired:stats(report.runs.map(r=>event(r,m.kind==='hero'?'chosenHero':'killedMonster',m.id))),...(m.kind==='monster'?{captured:stats(report.runs.map(r=>event(r,'capturedMonster',m.id)))}:{})}));
const checkpoints=report.checkpointsMinutes.map(minutes=>({minutes,metrics:Object.fromEntries(numberFields.map(n=>[n,stats(report.runs.map(r=>r.checkpoints.find(c=>c.minutes===minutes)[n]))]))}));
const result={schemaVersion:1,kind:'independent-final-v070-validation-analysis',agentId:'/root/balance',round:8,generatedAt:new Date().toISOString(),analysisGate:'Host COMPLETE notice then execution.endedAt; full100 only',executionPath,executionFileSha256:fileHash(executionPath),executionEndedAt:execution.endedAt,reportPath,reportFileSha256:fileHash(reportPath),sourceDigest:report.sourceDigest,evaluationDigest:report.evaluationDigest,protocolPath,protocolFileSha256:fileHash(protocolPath),protocolSha256:report.protocolSha256,rawSha256:report.rawSha256,buildSha256:report.build.sha256,manifest:{path:manifestPath,sha256:fileHash(manifestPath),binding:manifest.binding},experiment:report.experiment,parameters:experiment.parameters,actualSourceParameters:sourceParameters,actualCompiledParameters:compiledParameters,appVersion:'0.7.0',seeds:{start:1,count:100},policy:canonical,horizonMinutes:720,archiveInfo,commands:execution.commands,readinessChecks:execution.readinessChecks,rawFiles,metrics,goals,targetPassed,milestones,checkpoints,perSeed:rows,integrity:{status:errors.length?'FAIL':'PASS',errors},populationDefinition:'All100 with unreached null after finite; index floor((N-1)*q). Worst null whenever any observation is unreached.',conditionalDefinition:'Reached values only; separate distribution, never target denominator.',validationResultsForOptimization:false,newNumericalProposal:null,explorationModified:false,productSourceModified:false,evaluatorModified:false,gameMeasurementExecuted:false,buildExecuted:false,finalAuditExecuted:false,humanChecks:'PENDING',productReleaseVerified:false};
const destination=output+'/snapshot-complete.json';if(existsSync(destination))throw Error('Preserve existing snapshot; never overwrite.');
writeFileSync(destination,JSON.stringify(result,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({output:destination,bytes:readFileSync(destination).length,sha256:fileHash(destination),integrity:result.integrity,goals,targetPassed,samples:rows.length},null,2));
